import hashlib,re
from decimal import Decimal

def rows(conn,sql,args=()):
    with conn.cursor() as cursor:cursor.execute(sql,args);return cursor.fetchall()

def repair(conn,tenant,secret):
    if not conn.get_autocommit() or conn.server_status & 1:raise ValueError('clean autocommit connection required')
    if type(tenant) is not int or tenant<=0 or not isinstance(secret,str) or not re.fullmatch('[0-9a-f]{32,64}',secret):raise ValueError('approved tenant and hex secret required')
    conn.begin()
    try:
        scope=rows(conn,'SELECT approved FROM release_scope WHERE tenant=%s FOR UPDATE',(tenant,))
        if scope!=((1,),):raise ValueError('tenant not approved')
        people=rows(conn,'SELECT id,email FROM source_people WHERE tenant=%s ORDER BY id FOR SHARE',(tenant,))
        orders=rows(conn,'SELECT id,person_id,amount FROM source_orders WHERE tenant=%s ORDER BY id FOR SHARE',(tenant,))
        if any(email is not None and (not isinstance(email,str) or not email.isascii()) for _,email in people):raise ValueError('ASCII synthetic email contract')
        def digest(text):return hashlib.sha256(text.encode('utf-8')).hexdigest()
        mapping={person:digest(secret+'|person|'+str(tenant)+'|'+str(person)) for person,email in people}
        released=[(tenant,mapping[person],None if email is None else digest(secret+'|email|'+email.strip().lower()),'customer','[redacted]') for person,email in people]
        if any(person not in mapping for _,person,_ in orders):raise ValueError('orphan source order')
        rows(conn,'DELETE FROM released_orders WHERE tenant=%s',(tenant,))
        rows(conn,'DELETE FROM released_people WHERE tenant=%s',(tenant,))
        for row in released:rows(conn,'INSERT INTO released_people VALUES(%s,%s,%s,%s,%s)',row)
        for order,person,amount in orders:rows(conn,'INSERT INTO released_orders VALUES(%s,%s,%s,%s,%s)',(tenant,order,mapping[person],amount,'[redacted]'))
        conn.commit()
        return {'tenant':tenant,'people':len(people),'orders':len(orders),'total':str(sum((amount for _,_,amount in orders),Decimal('0.00')))}
    except Exception:conn.rollback();raise

